<div class="page-shell"><header class="page-hero wrap"><span class="eyebrow">Explore NCF</span><h1>Search</h1><form class="search-page" method="get" action="<?=url('search')?>"><label for="q">Search approved public content</label><div><input id="q" name="q" value="<?=e($q)?>" placeholder="Issues, discussions or articles"><button class="pill pill-dark">Search</button></div></form></header><div class="wrap content-grid"><?php foreach($results as $r):?><article class="content-card"><span class="eyebrow"><?=e($r['type'])?></span><h2><?=e($r['title'])?></h2><p><?=e(mb_strimwidth(strip_tags($r['excerpt']??''),0,220,'…'))?></p><a class="text-link" href="<?=url($r['url'])?>">View ↗</a></article><?php endforeach;?><?php if($q!==''&&!$results):?><div class="empty-state">No public results found.</div><?php endif;?></div></div>
